package main

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
)

// srcHeader starts weights.go. The first line matches Go's generated-code
// convention (^// Code generated .* DO NOT EDIT\.$), so linters and
// formatters skip the file.
const srcHeader = `// Code generated by extractweights from testdata/nmp.onnx; DO NOT EDIT.

package basicpitch

import (
	_ "embed"
	"encoding/binary"
	"fmt"
	"math"
)
`

// srcLoader is the fixed tail of weights.go: the tensor type and the embed
// loader. It uses encoding/binary rather than unsafe so it runs unchanged
// under js/wasm.
const srcLoader = `
// weightTensor is one decoded tensor of weights.bin.
type weightTensor struct {
	Shape []int
	Data  []float32
}

// loadWeights decodes weights.bin into fresh float32 slices, keyed by
// manifest name. It validates the manifest against the embedded bytes.
func loadWeights() (map[string]weightTensor, error) {
	if len(weightsBin) != 4*weightsTotal {
		return nil, fmt.Errorf("basicpitch: weights.bin: %d bytes, want %d", len(weightsBin), 4*weightsTotal)
	}

	out := make(map[string]weightTensor, len(weightManifest))
	next := 0

	for _, e := range weightManifest {
		n := 1
		for _, d := range e.Shape {
			n *= d
		}

		if e.Offset != next || e.Length != n || e.Offset+e.Length > weightsTotal {
			return nil, fmt.Errorf("basicpitch: weights.bin: tensor %q: offset %d, length %d, shape %v: inconsistent manifest",
				e.Name, e.Offset, e.Length, e.Shape)
		}

		data := make([]float32, e.Length)
		raw := weightsBin[4*e.Offset : 4*(e.Offset+e.Length)]

		for i := range data {
			data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[4*i:]))
		}

		out[e.Name] = weightTensor{Shape: append([]int(nil), e.Shape...), Data: data}
		next += e.Length
	}

	if next != weightsTotal {
		return nil, fmt.Errorf("basicpitch: weights.bin: manifest covers %d of %d values", next, weightsTotal)
	}

	return out, nil
}
`

// generateSource renders weights.go for the tensors in manifest order and
// formats it with go/format.
func generateSource(tensors []namedTensor, sha string) ([]byte, error) {
	var b bytes.Buffer

	b.WriteString(srcHeader)
	fmt.Fprintf(&b, `
// nmpONNXSHA256 is the SHA-256 of the nmp.onnx the weights were extracted
// from (basic-pitch v0.4.0, testdata/README.md).
const nmpONNXSHA256 = %q

// Names of the tensors in weights.bin. Kernels are HWIO
// (hwio[h][w][i][o] = oihw[o][i][h][w]); see docs/port-spec.md §3 and §4.
const (
`, sha)

	for _, t := range tensors {
		fmt.Fprintf(&b, "\tweight%s = %q\n", t.ident, t.name)
	}

	b.WriteString(`)

// weightsBin holds the tensors of weightManifest as concatenated
// little-endian float32 values.
//
//go:embed weights.bin
var weightsBin []byte

// weightEntry locates one tensor in weightsBin. Offset and Length count
// float32 elements, not bytes; Length is the product of Shape.
type weightEntry struct {
	Name   string
	Shape  []int
	Offset int
	Length int
}

`)

	offset := 0

	fmt.Fprintf(&b, "// weightsTotal is the number of float32 values in weightsBin.\nconst weightsTotal = %d\n\n", total(tensors))
	b.WriteString("// weightManifest lists the tensors of weightsBin in storage order.\nvar weightManifest = [...]weightEntry{\n")

	for _, t := range tensors {
		n := 1
		dims := make([]string, len(t.shape))

		for i, d := range t.shape {
			n *= d
			dims[i] = fmt.Sprint(d)
		}

		if n != len(t.data) {
			return nil, fmt.Errorf("extractweights: tensor %q: shape %v holds %d values, have %d", t.name, t.shape, n, len(t.data))
		}

		fmt.Fprintf(&b, "\t{Name: weight%s, Shape: []int{%s}, Offset: %d, Length: %d},\n",
			t.ident, strings.Join(dims, ", "), offset, len(t.data))

		offset += len(t.data)
	}

	b.WriteString("}\n")
	b.WriteString(srcLoader)

	src, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("extractweights: format weights.go: %w", err)
	}

	return src, nil
}

// total returns the number of float32 values of all tensors.
func total(tensors []namedTensor) int {
	n := 0
	for _, t := range tensors {
		n += len(t.data)
	}

	return n
}
